import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"基本用法 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"运行原始 SQL 查询","slug":"运行原始-sql-查询","link":"#运行原始-sql-查询","children":[{"level":3,"title":"查询记录","slug":"查询记录","link":"#查询记录","children":[]},{"level":3,"title":"修改记录","slug":"修改记录","link":"#修改记录","children":[]},{"level":3,"title":"通用语句","slug":"通用语句","link":"#通用语句","children":[]}]},{"level":2,"title":"多个数据库连接","slug":"多个数据库连接","link":"#多个数据库连接","children":[]},{"level":2,"title":"数据库事务","slug":"数据库事务","link":"#数据库事务","children":[]},{"level":2,"title":"数据库事件","slug":"数据库事件","link":"#数据库事件","children":[{"level":3,"title":"查询日志","slug":"查询日志","link":"#查询日志","children":[]}]}],"relativePath":"3.x/zh-cn/extend/database/basics.md","filePath":"3.x/zh-cn/extend/database/basics.md"}'),r={name:"3.x/zh-cn/extend/database/basics.md"};function d(k,a,g,h,v,b){const p=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[t(p),a[0]||(a[0]=s("h1",null,"基本用法",-1)),t(o),a[1]||(a[1]=s("p",null,[n("连接数据库并运行查询是一个简单的过程，支持使用原始 SQL、"),s("a",{href:"./query.html"},"查询构建器"),n("或"),s("a",{href:"./model.html"},"活动记录模型"),n("。管理数据库表和填充种子数据由"),s("a",{href:"./structure.html"},"迁移和种子填充流程"),n("处理。")],-1)),a[2]||(a[2]=s("p",null,[n("原始 SQL 和使用查询构建器执行更快，应该用于简单任务。活动记录是流行框架 Ruby On Rails 使用的一种方法。它为执行创建、读取、更新和删除数据库记录等重复任务提供了简单的接口。您可以在 "),s("a",{href:"http://en.wikipedia.org/wiki/Active_record_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Wikipedia 上了解更多关于活动记录模式的信息"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n("。")],-1)),a[3]||(a[3]=u(`<h2 id="运行原始-sql-查询"><a href="#运行原始-sql-查询" class="header-anchor">#</a> 运行原始 SQL 查询</h2><p>配置好数据库连接后，您可以使用 <code>Db</code> 门面运行查询。<code>Db</code> 门面为每种类型的查询提供了方法：<code>select</code>、<code>update</code>、<code>insert</code>、<code>delete</code> 和 <code>statement</code>。</p><h3 id="查询记录"><a href="#查询记录" class="header-anchor">#</a> 查询记录</h3><p>要运行基本查询，请使用 <code>Db</code> 门面上的 <code>select</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where active = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>传递给 <code>select</code> 方法的第一个参数是原始 SQL 查询，第二个参数是需要绑定到查询的任何参数绑定。通常，这些是 <code>where</code> 子句约束的值。参数绑定提供了针对 SQL 注入的保护。</p><p><code>select</code> 方法将始终返回一个结果 <code>array</code>。数组中的每个结果将是一个 PHP <code>stdClass</code> 对象，允许您访问结果的值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您可以使用命名绑定来执行查询，而不是使用 <code>?</code> 来表示您的参数绑定。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where id = :id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果数据库查询可能产生单个值，可以使用 <code>scalar</code> 方法获取。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">scalar</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select count(*) as count from menu_items&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="修改记录"><a href="#修改记录" class="header-anchor">#</a> 修改记录</h3><p>要执行 <code>insert</code> 语句，您可以使用 <code>Db</code> 门面上的 <code>insert</code> 方法。与 <code>select</code> 一样，此方法将原始 SQL 查询作为第一个参数，将绑定作为第二个参数。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;insert into users (id, name) values (?, ?)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>update</code> 方法应该用于更新数据库中的现有记录。该方法将返回受该语句影响的行数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;update users set votes = 100 where name = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>delete</code> 方法应该用于从数据库中删除记录。与 <code>update</code> 一样，将返回被删除的行数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deleted</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;delete from users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="通用语句"><a href="#通用语句" class="header-anchor">#</a> 通用语句</h3><p>某些数据库语句不应该返回任何值。对于这些类型的操作，您可以使用 <code>Db</code> 门面上的 <code>statement</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">statement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;drop table users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="多个数据库连接"><a href="#多个数据库连接" class="header-anchor">#</a> 多个数据库连接</h2><p>当<a href="./../../setup/database-config.html">使用多个连接</a>时，您可以通过 <code>Db</code> 门面上的 <code>connection</code> 方法访问每个连接。传递给 <code>connection</code> 方法的 <code>name</code> 应该对应于 <code>config/database.php</code> 配置文件中列出的连接之一。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以使用连接实例上的 <code>getPdo</code> 方法访问原始的底层 PDO 实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pdo</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getPdo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="数据库事务"><a href="#数据库事务" class="header-anchor">#</a> 数据库事务</h2><p>要在数据库事务中运行一组操作，您可以使用 <code>Db</code> 门面上的 <code>transaction</code> 方法。如果在事务 <code>Closure</code> 中抛出异常，事务将自动回滚。如果 <code>Closure</code> 成功执行，事务将自动提交。使用 <code>transaction</code> 方法时，您不需要担心手动回滚或提交。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">transaction</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果您想手动开始一个事务并完全控制回滚和提交，您可以使用 <code>Db</code> 门面上的 <code>beginTransaction</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">beginTransaction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以通过 <code>rollBack</code> 方法回滚事务：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">rollBack</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>最后，您可以通过 <code>commit</code> 方法提交事务：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>使用 <code>Db</code> 门面的事务方法还可以控制<a href="./query.html">查询构建器</a>和<a href="./model.html">模型查询</a>的事务。</p></div><h2 id="数据库事件"><a href="#数据库事件" class="header-anchor">#</a> 数据库事件</h2><p>如果您希望接收应用程序执行的每个 SQL 查询，您可以使用 <code>listen</code> 方法。此方法对于记录查询或调试非常有用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$sql</span><span class="token punctuation">,</span> <span class="token variable">$bindings</span><span class="token punctuation">,</span> <span class="token variable">$time</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以在<a href="./../extending.html">插件注册文件</a>的 <code>boot</code> 方法中注册您的查询监听器。或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以在其中放置此逻辑。</p><h3 id="查询日志"><a href="#查询日志" class="header-anchor">#</a> 查询日志</h3><p>启用查询日志时，内存中会保留当前请求已运行的所有查询的日志。调用 <code>enableQueryLog</code> 方法启用此功能。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">enableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要获取已执行查询的数组，您可以使用 <code>getQueryLog</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$queries</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">getQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>但是，在某些情况下，例如插入大量行时，这可能导致应用程序使用过多内存。要禁用日志，您可以使用 <code>disableQueryLog</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">disableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>对于更快速的调试，调用 <code>trace_sql</code> <a href="./../services/log.html">辅助函数</a>可能更有用。</p></div>`,49))])}const x=c(r,[["render",d]]);export{f as __pageData,x as default};
